// When sets expectation for the WatchProgress.UpdatePosition which will trigger the result defined by the following
// Then helper
func (mmUpdatePosition *mWatchProgressMockUpdatePosition) When(ctx context.Context, userID uuid.UUID, videoID uuid.UUID, positionMs int64, now time.Time) *WatchProgressMockUpdatePositionExpectation {
	if mmUpdatePosition.mock.funcUpdatePosition != nil {
		mmUpdatePosition.mock.t.Fatalf("WatchProgressMock.UpdatePosition mock is already set by Set")
	}

	expectation := &WatchProgressMockUpdatePositionExpectation{
		mock:               mmUpdatePosition.mock,
		params:             &WatchProgressMockUpdatePositionParams{ctx, userID, videoID, positionMs, now},
		expectationOrigins: WatchProgressMockUpdatePositionExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmUpdatePosition.expectations = append(mmUpdatePosition.expectations, expectation)
	return expectation
}

// Then sets up WatchProgress.UpdatePosition return parameters for the expectation previously defined by the When method
func (e *WatchProgressMockUpdatePositionExpectation) Then(w1 domain.WatchProgress, err error) *WatchProgressMock {
	e.results = &WatchProgressMockUpdatePositionResults{w1, err}
	return e.mock
}

// Times sets number of times WatchProgress.UpdatePosition should be invoked
func (mmUpdatePosition *mWatchProgressMockUpdatePosition) Times(n uint64) *mWatchProgressMockUpdatePosition {
	if n == 0 {
		mmUpdatePosition.mock.t.Fatalf("Times of WatchProgressMock.UpdatePosition mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmUpdatePosition.expectedInvocations, n)
	mmUpdatePosition.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmUpdatePosition
}

func (mmUpdatePosition *mWatchProgressMockUpdatePosition) invocationsDone() bool {
	if len(mmUpdatePosition.expectations) == 0 && mmUpdatePosition.defaultExpectation == nil && mmUpdatePosition.mock.funcUpdatePosition == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpdatePosition.mock.afterUpdatePositionCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpdatePosition.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// UpdatePosition implements mm_repository.WatchProgress
func (mmUpdatePosition *WatchProgressMock) UpdatePosition(ctx context.Context, userID uuid.UUID, videoID uuid.UUID, positionMs int64, now time.Time) (w1 domain.WatchProgress, err error) {
	mm_atomic.AddUint64(&mmUpdatePosition.beforeUpdatePositionCounter, 1)
	defer mm_atomic.AddUint64(&mmUpdatePosition.afterUpdatePositionCounter, 1)

	mmUpdatePosition.t.Helper()

	if mmUpdatePosition.inspectFuncUpdatePosition != nil {
		mmUpdatePosition.inspectFuncUpdatePosition(ctx, userID, videoID, positionMs, now)
	}

	mm_params := WatchProgressMockUpdatePositionParams{ctx, userID, videoID, positionMs, now}

	// Record call args
	mmUpdatePosition.UpdatePositionMock.mutex.Lock()
	mmUpdatePosition.UpdatePositionMock.callArgs = append(mmUpdatePosition.UpdatePositionMock.callArgs, &mm_params)
	mmUpdatePosition.UpdatePositionMock.mutex.Unlock()

	for _, e := range mmUpdatePosition.UpdatePositionMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.w1, e.results.err
		}
	}

	if mmUpdatePosition.UpdatePositionMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpdatePosition.UpdatePositionMock.defaultExpectation.Counter, 1)
		mm_want := mmUpdatePosition.UpdatePositionMock.defaultExpectation.params
		mm_want_ptrs := mmUpdatePosition.UpdatePositionMock.defaultExpectation.paramPtrs

		mm_got := WatchProgressMockUpdatePositionParams{ctx, userID, videoID, positionMs, now}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.userID != nil && !minimock.Equal(*mm_want_ptrs.userID, mm_got.userID) {
				mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameter userID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.originUserID, *mm_want_ptrs.userID, mm_got.userID, minimock.Diff(*mm_want_ptrs.userID, mm_got.userID))
			}

			if mm_want_ptrs.videoID != nil && !minimock.Equal(*mm_want_ptrs.videoID, mm_got.videoID) {
				mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameter videoID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.originVideoID, *mm_want_ptrs.videoID, mm_got.videoID, minimock.Diff(*mm_want_ptrs.videoID, mm_got.videoID))
			}

			if mm_want_ptrs.positionMs != nil && !minimock.Equal(*mm_want_ptrs.positionMs, mm_got.positionMs) {
				mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameter positionMs, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.originPositionMs, *mm_want_ptrs.positionMs, mm_got.positionMs, minimock.Diff(*mm_want_ptrs.positionMs, mm_got.positionMs))
			}

			if mm_want_ptrs.now != nil && !minimock.Equal(*mm_want_ptrs.now, mm_got.now) {
				mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameter now, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.originNow, *mm_want_ptrs.now, mm_got.now, minimock.Diff(*mm_want_ptrs.now, mm_got.now))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpdatePosition.t.Errorf("WatchProgressMock.UpdatePosition got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdatePosition.UpdatePositionMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpdatePosition.UpdatePositionMock.defaultExpectation.results
		if mm_results == nil {
			mmUpdatePosition.t.Fatal("No results are set for the WatchProgressMock.UpdatePosition")
		}
		return (*mm_results).w1, (*mm_results).err
	}
	if mmUpdatePosition.funcUpdatePosition != nil {
		return mmUpdatePosition.funcUpdatePosition(ctx, userID, videoID, positionMs, now)
	}
	mmUpdatePosition.t.Fatalf("Unexpected call to WatchProgressMock.UpdatePosition. %v %v %v %v %v", ctx, userID, videoID, positionMs, now)
	return
}

// UpdatePositionAfterCounter returns a count of finished WatchProgressMock.UpdatePosition invocations
func (mmUpdatePosition *WatchProgressMock) UpdatePositionAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdatePosition.afterUpdatePositionCounter)
}

// UpdatePositionBeforeCounter returns a count of WatchProgressMock.UpdatePosition invocations
func (mmUpdatePosition *WatchProgressMock) UpdatePositionBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdatePosition.beforeUpdatePositionCounter)
}

// Calls returns a list of arguments used in each call to WatchProgressMock.UpdatePosition.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmUpdatePosition *mWatchProgressMockUpdatePosition) Calls() []*WatchProgressMockUpdatePositionParams {
	mmUpdatePosition.mutex.RLock()

	argCopy := make([]*WatchProgressMockUpdatePositionParams, len(mmUpdatePosition.callArgs))
	copy(argCopy, mmUpdatePosition.callArgs)

	mmUpdatePosition.mutex.RUnlock()

	return argCopy
}

// MinimockUpdatePositionDone returns true if the count of the UpdatePosition invocations corresponds
// the number of defined expectations
func (m *WatchProgressMock) MinimockUpdatePositionDone() bool {
	if m.UpdatePositionMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpdatePositionMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpdatePositionMock.invocationsDone()
}

// MinimockUpdatePositionInspect logs each unmet expectation
func (m *WatchProgressMock) MinimockUpdatePositionInspect() {
	for _, e := range m.UpdatePositionMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to WatchProgressMock.UpdatePosition at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdatePositionCounter := mm_atomic.LoadUint64(&m.afterUpdatePositionCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdatePositionMock.defaultExpectation != nil && afterUpdatePositionCounter < 1 {
		if m.UpdatePositionMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to WatchProgressMock.UpdatePosition at\n%s", m.UpdatePositionMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to WatchProgressMock.UpdatePosition at\n%s with params: %#v", m.UpdatePositionMock.defaultExpectation.expectationOrigins.origin, *m.UpdatePositionMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdatePosition != nil && afterUpdatePositionCounter < 1 {
		m.t.Errorf("Expected call to WatchProgressMock.UpdatePosition at\n%s", m.funcUpdatePositionOrigin)
	}

	if !m.UpdatePositionMock.invocationsDone() && afterUpdatePositionCounter > 0 {
		m.t.Errorf("Expected %d calls to WatchProgressMock.UpdatePosition at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdatePositionMock.expectedInvocations), m.UpdatePositionMock.expectedInvocationsOrigin, afterUpdatePositionCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *WatchProgressMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockApplyInspect()

			m.MinimockInsertEmptyInspect()

			m.MinimockOnDurationKnownInspect()

			m.MinimockSelectByUserAndVideoIDsInspect()

			m.MinimockSelectByVideoIDsInspect()

			m.MinimockSelectForUpdateInspect()

			m.MinimockUpdatePositionInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *WatchProgressMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *WatchProgressMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockApplyDone() &&
		m.MinimockInsertEmptyDone() &&
		m.MinimockOnDurationKnownDone() &&
		m.MinimockSelectByUserAndVideoIDsDone() &&
		m.MinimockSelectByVideoIDsDone() &&
		m.MinimockSelectForUpdateDone() &&
		m.MinimockUpdatePositionDone()
}
